1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isWithinOneStep = (coordinate: number, other: number): boolean =>
7	  Math.abs(coordinate - other) <= 1;
8	
9	const isNeighbor = (cell: Cell, other: Cell): boolean => {
10	  const [x, y] = cell;
11	  const [otherX, otherY] = other;
12	  return (
13	    isWithinOneStep(x, otherX) &&
14	    isWithinOneStep(y, otherY) &&
15	    !isSameCell(cell, other)
16	  );
17	};
18	
19	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
20	  liveCells.filter((other) => isNeighbor(cell, other)).length;
21	
22	const NEIGHBOR_OFFSETS: Cell[] = [
23	  [-1, -1],
24	  [-1, 0],
25	  [-1, 1],
26	  [0, -1],
27	  [0, 1],
28	  [1, -1],
29	  [1, 0],
30	  [1, 1],
31	];
32	
33	const neighborsOf = ([x, y]: Cell): Cell[] =>
34	  NEIGHBOR_OFFSETS.map(([dx, dy]): Cell => [x + dx, y + dy]);
35	
36	const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
37	  liveCells.some((other) => isSameCell(cell, other));
38	
39	const survives = (cell: Cell, liveCells: Cell[]): boolean => {
40	  const neighborCount = countLiveNeighbors(cell, liveCells);
41	  return neighborCount === 2 || neighborCount === 3;
42	};
43	
44	const isBorn = (cell: Cell, liveCells: Cell[]): boolean =>
45	  !isAlive(cell, liveCells) && countLiveNeighbors(cell, liveCells) === 3;
46	
47	const withoutDuplicates = (cells: Cell[]): Cell[] =>
48	  cells.filter(
49	    (cell, index) =>
50	      cells.findIndex((other) => isSameCell(cell, other)) === index,
51	  );
52	
53	export function nextGeneration(liveCells: Cell[]): Cell[] {
54	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
55	  const births = withoutDuplicates(liveCells.flatMap(neighborsOf)).filter(
56	    (candidate) => isBorn(candidate, liveCells),
57	  );
58	  return [...survivors, ...births];
59	}
